@js:(function(){
var s='';
try{s=String(src);}catch(e){}
if(s.length<500){s=String(result);}
var o=[],m,re=/\(\s*'([A-Za-z0-9+\/=]{40,})'\s*\)/g;
while((m=re.exec(s))!==null){o.push(java.base64Decode(m[1]));}
if(o.length<1){re=/'([A-Za-z0-9+\/=]{40,})'/g;while((m=re.exec(s))!==null){o.push(java.base64Decode(m[1]));}}
if(o.length>0){return o.join('\n');}
var seg=s,i=s.indexOf('<div class="word_read">');
if(i>-1){seg=s.slice(i);}
var ks=[seg.indexOf('<script language=javascript>'),seg.indexOf('<div class="footer"'),seg.indexOf('</body>'),seg.indexOf('相邻推荐')];
var kk=0;
for(var z=0;z<ks.length;z++){if(ks[z]>0){if(kk<1){kk=ks[z];}else{if(ks[z]<kk){kk=ks[z];}}}}
if(kk>0){seg=seg.slice(0,kk);}
seg=seg.replace(/<script[\s\S]*?<\/script>/gi,'');
seg=seg.replace(/<div class="read_btn"[\s\S]*?<\/div>/gi,'');
var mm=seg.match(/<p[\s\S]*?<\/p>/gi);
var out=[];
if(mm){for(var q=0;q<mm.length;q++){var t=mm[q];if(t.indexOf('请勿开启')<0){if(t.indexOf('相邻推荐')<0){if(t.indexOf('本站所有')<0){if(t.indexOf('Copyright')<0){out.push(t);}}}}}}
return out.join('\n');
})()

